;-----------------------------------------------------------------------------
;  FUNCTION NAME: SAR8_1_SelectADCChannel
;
;  DESCRIPTION:
;   Select the ADC channel from one of all Port 0 pins or from ACB00 and ACB01
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  Byte:
;
;  RETURNS: No return value
;
;  SIDE EFFECTS:
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to preserve their values across calls to fastcall16
;    functions.
;
 SAR8_1_SelectADCChannel:
_SAR8_1_SelectADCChannel:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and  A, 0x78                                    ; remove extraneous data if any
    mov  X, SP
    push A
    mov  A, reg[SAR8_1_CONTROL_0_REG]
    and  A, ~0x78
    or   A, [X]                                     ; clear previous channel
    mov  reg[SAR8_1_CONTROL_0_REG], A
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret
.ENDSECTION

