.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: SAR8_1_SetHighAlignSrc
;
;  DESCRIPTION:
;    Sets path for high align source
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  input BYTE      Value:
;                              0 = None
;                              1 = DBB00
;                              2 = DBB01
;                              3 = DCB02
;                              4 = DCB03
;
;  RETURNS: No return value
;
;  SIDE EFFECTS:
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to preserve their values across calls to fastcall16
;    functions.
;
 SAR8_1_SetHighAlignSrc:
_SAR8_1_SetHighAlignSrc:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and  A, 0x07                                      ; remove extraneous data if any
    index   SAR8_1_AlignSrc
    asl  A
    mov  X, SP
    push A
    M8C_SetBank1
    mov  A, reg[SAR8_1_TRIGGER_SRC_REG]
    and  A, 0x55   ; empty trigger high bits: 7,5,3,1
    or   A, [X]
    mov  reg[SAR8_1_TRIGGER_SRC_REG], A
    M8C_SetBank0
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret
.ENDSECTION

