.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: SAR8_1_SetScale
;
;  DESCRIPTION:
;    Divides raw ADC results by 2^n depending on input argument n.
;    ***check for corner case of 111!
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  Byte:
;                     00h = no divide
;                     08h = divide by 2
;                     10h = divide by 4
;                     18h = divide by 8
;                     20h = divide by 16
;                     28h = divide by 32
;                     30h = divide by 64
;
;  RETURNS: No return value
;
;  SIDE EFFECTS:
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to preserve their values across calls to fastcall16
;    functions.
;
 SAR8_1_SetScale:
_SAR8_1_SetScale:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and  A, 0x38                                    ; remove extraneous data if any
    cmp  A, 0x38                                    ; set scale=64 for invalid entry
    jnz  .L1
    mov  A, 0x30
.L1:
    mov  X, SP
    push A
    M8C_SetBank1
    mov  A, reg[SAR8_1_CONTROL_2_REG]
    and  A, ~0x38                                   ; clear previous settings
    or   A, [X]
    mov  reg[SAR8_1_CONTROL_2_REG], A
    M8C_SetBank0
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret
.ENDSECTION

.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: SAR8_1_SetRunMode
;
;  DESCRIPTION:
;    Sets run mode for ADC to Free Run or One-Shot
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  Byte:  0 = ADC in One-Shot Mode
;                     1 = ADC in Free Running Mode
;
;  RETURNS: No return value
;
;  SIDE EFFECTS:
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to preserve their values across calls to fastcall16
;    functions.
;
 SAR8_1_SetRunMode:
_SAR8_1_SetRunMode:
    RAM_PROLOGUE RAM_USE_CLASS_1
    M8C_SetBank1
    and  A, 0x01                ; remove extraneous data if any
    jnz  .FreeRun
    and  reg[SAR8_1_CONTROL_2_REG], ~0x40
    jmp  .Done
.FreeRun:
    or   reg[SAR8_1_CONTROL_2_REG], 0x40
.Done:
    M8C_SetBank0
    RAM_EPILOGUE RAM_USE_CLASS_1
    ret
.ENDSECTION

.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: SAR8_1_SetClock
;
;  DESCRIPTION:
;        Sets the @INSTANCE_NAME clock rate.
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  Byte:
;                     00h =SysClk
;                     01h = SysClk divide by 2
;                     02h = SysClk divide by 4
;                     03h = SysClk divide by 8
;                     04h = SysClk divide by 16
;                     05h = SysClk divide by 32
;                     06h = SysClk divide by 64
;
;  RETURNS: No return value
;
;  SIDE EFFECTS:
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to preserve their values across calls to fastcall16
;    functions.
;
 SAR8_1_SetClock:
_SAR8_1_SetClock:
    RAM_PROLOGUE RAM_USE_CLASS_2
    cmp  A, 0x07                                    ; set clock=64 for invalid entry
    jc  .L1
    mov  A, 0x06
.L1:
    mov  X, SP
    push A
    M8C_SetBank1
    mov  A, reg[SAR8_1_CONTROL_2_REG]
    and  A, ~0x07                                   ; clear previous settings
    or   A, [X]
    mov  reg[SAR8_1_CONTROL_2_REG], A
    M8C_SetBank0
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret
.ENDSECTION


